import React, { useState, useEffect, useRef } from 'react';
import { SKILL_CATEGORIES, CV_DATA } from '../constants';

const useScrollReveal = () => {
  const [active, setActive] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setActive(true);
        }
      },
      { threshold: 0.1 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);

  return { ref, active };
};

const SkillIcon: React.FC<{ name: string; icon?: string; className?: string }> = ({ name, icon, className }) => {
  const [hasError, setHasError] = useState(false);

  const stringToGradient = (str: string) => {
    const hash = str.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    const colors = [
      'from-pink-500 to-rose-500',
      'from-blue-500 to-indigo-500',
      'from-emerald-500 to-teal-500',
      'from-amber-500 to-orange-500',
      'from-purple-500 to-violet-500',
      'from-cyan-500 to-blue-500'
    ];
    return colors[hash % colors.length];
  };

  if (!icon || hasError) {
    return (
      <div className={`flex items-center justify-center bg-gradient-to-br ${stringToGradient(name)} rounded-2xl shadow-lg border border-white/10 group-hover:scale-110 transition-transform duration-500 ${className}`}>
        <span className="text-white font-black text-xl select-none">
          {name.substring(0, 2).toUpperCase()}
        </span>
      </div>
    );
  }

  return (
    <img 
      src={`https://skillicons.dev/icons?i=${icon}`} 
      alt={name}
      className={`object-contain transition-all duration-500 group-hover:scale-110 drop-shadow-[0_0_15px_rgba(255,255,255,0.3)] ${className}`}
      onError={() => setHasError(true)}
    />
  );
};

