const useScrollReveal = () => {
  const [active, setActive] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setActive(true);
        }
      },
      { threshold: 0.1 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);

  return { ref, active };
};

const SkillIcon: React.FC<{ name: string; icon?: string; className?: string }> = ({ name, icon, className }) => {
  const [hasError, setHasError] = useState(false);

  // Generate a high-end stylized fallback for missing logos
  const generateFallback = (str: string) => {
    const hash = str.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    const colors = [
      'from-pink-500 via-rose-500 to-orange-400',
      'from-blue-600 via-indigo-500 to-cyan-400',
      'from-emerald-500 via-teal-500 to-lime-400',
      'from-amber-500 via-orange-500 to-red-400',
      'from-purple-600 via-violet-500 to-pink-400',
      'from-cyan-500 via-sky-500 to-blue-400'
    ];
    const gradient = colors[hash % colors.length];

    // Create a fancy acronym or short version
    const acronym = str.split(/[ /]/).map(word => word[0]).join('').substring(0, 3).toUpperCase();

    return (
      <div className={`relative flex items-center justify-center bg-gradient-to-br ${gradient} rounded-2xl shadow-lg border border-white/20 group-hover:scale-110 transition-all duration-500 overflow-hidden ${className}`}>
        <div className="absolute inset-0 bg-black/10 backdrop-blur-[2px]"></div>
        <div className="relative z-10 flex flex-col items-center">
