            {acronym}
          </span>
          <div className="w-4 h-0.5 bg-white/40 mt-1 rounded-full"></div>
        </div>
        {/* Decorative elements to make it look like a real logo */}
        <div className="absolute top-0 right-0 w-4 h-4 bg-white/10 rounded-full -mr-1 -mt-1 blur-sm"></div>
        <div className="absolute bottom-0 left-0 w-4 h-4 bg-black/20 rounded-full -ml-1 -mb-1 blur-sm"></div>
      </div>
    );
  };

  if (!icon || hasError) {
    return generateFallback(name);
  }

  return (
    <img 
      src={`https://skillicons.dev/icons?i=${icon}`} 
      alt={name}
      className={`object-contain transition-all duration-500 group-hover:scale-110 drop-shadow-[0_0_15px_rgba(255,255,255,0.3)] ${className}`}
